<?php
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');if($title!==''){db()->prepare('INSERT INTO goals(title,description,target_date,priority) VALUES(?,?,?,?)')->execute([$title,trim($_POST['description']??''),$_POST['target_date']?:null,$_POST['priority']??'medium']);flash('Learning goal created.');}redirect('index.php?page=goals');}
if(isset($_GET['done'])){db()->prepare("UPDATE goals SET status='completed',completed_at=NOW() WHERE id=?")->execute([(int)$_GET['done']]);flash('Goal marked completed.');redirect('index.php?page=goals');}
$rows=db()->query('SELECT * FROM goals ORDER BY FIELD(status,"active","completed"),target_date')->fetchAll();
?><div class="page-heading"><div><p class="eyebrow">DIRECTION & PURPOSE</p><h1>Learning Goals</h1><p class="muted">Turn long-term ambitions into achievable targets.</p></div></div><div class="two-col"><section class="card"><h2>Create a goal</h2><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Goal title</label><input name="title" required><label>Description</label><textarea name="description"></textarea><label>Target date</label><input type="date" name="target_date"><label>Priority</label><select name="priority"><option value="high">High</option><option value="medium" selected>Medium</option><option value="low">Low</option></select><button class="btn primary">Create goal</button></form></section><section class="card"><h2>My goals</h2><?php if(!$rows):?><div class="empty-state compact">No goals created yet.</div><?php else:foreach($rows as $g):?><div class="list-item"><div class="grow"><b><?=e($g['title'])?></b><small><?=e($g['description']??'')?></small><small>Target: <?=e($g['target_date']??'Not set')?> · <?=e($g['priority'])?></small></div><?php if($g['status']==='active'):?><a class="btn small secondary" href="index.php?page=goals&done=<?=$g['id']?>">Complete</a><?php else:?><span class="pill success">Completed</span><?php endif;?></div><?php endforeach;endif;?></section></div>
